import{_ as t,o as i,c as r,a5 as a}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Add Material — implementation evidence, 2026-10-24","description":"","frontmatter":{},"headers":[],"relativePath":"feature/repository/add-material-repository/evidence.md","filePath":"feature/repository/add-material-repository/evidence.md"}'),o={name:"feature/repository/add-material-repository/evidence.md"};function n(d,e,s,l,c,p){return i(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="add-material-—-implementation-evidence-2026-10-24" tabindex="-1">Add Material — implementation evidence, 2026-10-24 <a class="header-anchor" href="#add-material-—-implementation-evidence-2026-10-24" aria-label="Permalink to &quot;Add Material — implementation evidence, 2026-10-24&quot;">​</a></h1><p><strong>Status: implemented locally, acceptance incomplete / NO-GO for activation.</strong> Ticket01 only; no implementation of View/PATCH/Trash/Download FRs. Existing readers/watermark/Post callers changed only where needed for private upload compatibility. No live migration, deploy, commit or push.</p><h2 id="baseline-and-authority" tabindex="-1">Baseline and authority <a class="header-anchor" href="#baseline-and-authority" aria-label="Permalink to &quot;Baseline and authority&quot;">​</a></h2><p>Business baseline <code>620855477dc6cd7f4b9a0da824c260ae04649e64</code>; Web baseline <code>b4a158ef5b10241af53878981db1b17b722a4392</code>. Current branch <code>feat/tuan-sprint-9</code>. Infrastructure already had unrelated subscription docs and Repository planning docs in its worktree; those are not new implementation evidence. Historical <code>spec-before-planning</code> snapshot does not override BR01–BR25 or current <code>spec/plan/task/test</code>.</p><p>Rules read: business CLAUDE.md/rule.md, web AGENTS.md/CLAUDE.md/rule.md/STRUCTURE, infrastructure workflow and relevant local skills. Applied implement/TDD/code-review workflow.</p><h2 id="delivered-code" tabindex="-1">Delivered code <a class="header-anchor" href="#delivered-code" aria-label="Permalink to &quot;Delivered code&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Implementation</th></tr></thead><tbody><tr><td>Existing API</td><td>Reused upload-session/confirm and multipart ≤5 MiB; TASK default/assignee guard, LIBRARY context, no original WebP conversion</td></tr><tr><td>ACL</td><td>PG account/workspace/membership/profile resolver; no implicit OWNER file rights; ancestor checks; list resolves membership once and batches ancestors</td></tr><tr><td>Quota</td><td>PG pool→Agency→reservation lock order; effective paid catalog total; BASIC20 GiB; stable provider; atomic reserve/commit/release and ledger</td></tr><tr><td>Schema</td><td>Additive PG usage/reservation/ledger/pool SQL, Mongo optional legacy validator/session/reference/provider-key indexes, explicit DRY_RUN wrapper</td></tr><tr><td>Storage</td><td>Private provider router through existing FileStorageService, default-off flags, conditional ETag copy, bounded HEAD/range/timeout, no new Redis/service</td></tr><tr><td>Saga</td><td>Durable Mongo majority checkpoints, PG claims, unique canonical per promotion token, actual-size/MIME checks, Mongo transaction publication/pins, idempotent READY replay</td></tr><tr><td>Cleanup</td><td>Delayed staging delete+HEAD absence; physical hold clears once only after newer authoritative inventory; ambiguous copy retains quota, confirmed missing after lifetime bound cancels safely</td></tr><tr><td>Agency</td><td>Existing create transaction applies pool guard and initializes verified-empty usage for newly created Agency while Repository is enabled</td></tr><tr><td>Watermark</td><td>Private original read, trusted logo origin, bounded raster dimensions, reservation before processing, actual PNG usage, inherited ACL/purpose/task/lineage</td></tr><tr><td>Existing editor</td><td>Stable material_id in Post/Task media, atomic reference pin reconciliation including removal of final material, fresh private URL on render/publish, no signed URL persistence/log payload</td></tr><tr><td>Web</td><td>Typed session/PUT/confirm, progress/validation/retry/abort/workspace isolation, real Library upload form, vi/en parallel keys, PDF fallback</td></tr></tbody></table><p>The Library <strong>list remains its existing mock implementation</strong> until View ticket02. Newly confirmed uploads can be shown in the current view; this is not a server-backed Repository listing.</p><h2 id="executed-checks" tabindex="-1">Executed checks <a class="header-anchor" href="#executed-checks" aria-label="Permalink to &quot;Executed checks&quot;">​</a></h2><p>Windows 11 / Java21 / Maven offline / Docker Desktop29.9.2 / Node local dependencies. PostgreSQL <code>postgres:17-alpine</code>; Mongo <code>mongo:8.0</code> replica set, disposable containers only. Docker API compatibility property <code>-Dapi.version=1.44</code> is needed for this local Testcontainers version. An earlier run without it skipped Docker tests; skipped runs are <strong>not</strong> integration evidence.</p><table tabindex="0"><thead><tr><th>Check</th><th>Command / evidence</th><th>Actual</th></tr></thead><tbody><tr><td>Backend full suite</td><td><code>mvn -o -q -Dapi.version=1.44 test</code>; local <code>business/target/repository-full-test.log</code> and Surefire XML</td><td>Exit0; 183 suites, 1205 tests, 0 failures/errors, 93 skipped (1112 executed). Run before final small pin/preflight refinements; focused regressions follow</td></tr><tr><td>Focused G1</td><td><code>MaterialRepositoryIntegrationTest,StorageQuotaPostgresTest</code> with Docker API property</td><td>Real PG + Mongo transaction tests pass; binary adapter is in-memory and <strong>not G0</strong></td></tr><tr><td>Unit/regression</td><td><code>MaterialUploadPolicyTest,MaterialContentValidatorTest,MaterialAccessPolicyTest,MaterialUploadCoordinatorTest,RepositoryPostMediaTest,MaterialServiceImplTest,PostServiceImplTest</code></td><td>Focused runs pass; initial missing policy/container API tests failed before implementation</td></tr><tr><td>PG migration</td><td>SQL applied twice on disposable schema in StorageQuotaPostgresTest</td><td>Idempotent fixture run; concurrent15 GiB reservations accept one; commit replay no double count; paid-total/expiry and stale/95% pool guards pass</td></tr><tr><td>Pool accounting</td><td>StorageQuotaPostgresTest cleanup test</td><td>Hold remains until newer inventory, clears once, physical canonical usage remains</td></tr><tr><td>Mongo schema</td><td>Actual mongosh expansion applied twice per disposable fixture in final integration run</td><td>Replay pass; validator/indexes and transaction publication exercised; not a production legacy backfill</td></tr><tr><td>Post references</td><td>MaterialRepositoryIntegrationTest</td><td>Persisted Post has material_id and no signed URL; Post and Task Post remove final pin in same Mongo transaction</td></tr><tr><td>Web build</td><td><code>npm.cmd run build</code></td><td>Exit0, TypeScript + Vite build pass</td></tr><tr><td>Web typecheck</td><td><code>npm.cmd run type-check</code></td><td>Pass</td></tr><tr><td>Web full unit suite</td><td><code>npm.cmd test</code></td><td>3 files / 10 tests pass; Vitest include now covers repository-required tests/unit location</td></tr><tr><td>UI</td><td><code>BASE_URL=http://127.0.0.1:3000 npx.cmd playwright test tests/e2e/repository/add-material.spec.ts --workers=1 --reporter=line</code></td><td>4 pass; 375 light / 768 dark / 1440 light, keyboard focus, READY-only success, no JWT on PUT, quota error and OWNER control hidden</td></tr><tr><td>UI artifacts</td><td><code>brandhub-web/test-results/repository-add-material-*/repository-form-*.png</code></td><td>Form screenshots inspected; no horizontal page overflow. Existing shell/mock-list layout is outside this ticket</td></tr><tr><td>Lint</td><td>ESLint changed TS/TSX</td><td>0 errors; 3 pre-existing set-state-in-effect warnings in useEditorForm/MediaTab</td></tr><tr><td>Infra</td><td><code>./scripts/repository-migrate.ps1</code></td><td>DRY_RUN, no connection/write</td></tr><tr><td>Diff</td><td><code>git diff --check</code></td><td>No whitespace errors</td></tr></tbody></table><p>No E2E result here proves storage durability, provider compatibility or malware safety. Container validation is bounded structural checking (max128 ranges/2 MiB metadata/30s), not codec decoding, PDF stream execution, antivirus or a guarantee every valid complex container is supported.</p><h2 id="review-and-remaining-gates" tabindex="-1">Review and remaining gates <a class="header-anchor" href="#review-and-remaining-gates" aria-label="Permalink to &quot;Review and remaining gates&quot;">​</a></h2><p>Standards/Spec were reviewed independently through code-review. Fixed findings: per-row ACL N+1, safe recovery diagnostics, expiring Post URL persistence, staging/physical hold leakage, new Agency provisioning/capacity, missing-copy recovery and stale pins on final media removal.</p><p><strong>Not run / not complete:</strong></p><ul><li>TC-A01–03: no disposable rclone/Drive or AWS test endpoints/config were supplied. Presign, conditional-copy semantics, durable acknowledgement/restart/SSD-full/403/429 remain unverified.</li><li>G0 also needs gateway enforcement of upload size and maximum operation lifetime below24h, and a durable physical inventory feed ≤5 minutes old. None is deployed by this ticket.</li><li>Actual legacy object inventory/backfill and rollout against a representative data copy remain pending. Expansion leaves existing agencies inventory-unverified and legacy objects non-READY until verified.</li><li>Full per-step process-kill/timeout fault matrix, all revoked-ancestor races, real Mobile device contract, provider adapter integration and full watermark/private-logo production-shaped regression remain pending.</li><li>Future mutation/purge writers must use the provided revision/reference fence. No Update/Remove lifecycle is implemented here; PURGE_RELEASE belongs to that later workflow.</li></ul><p>Both provider verified flags and writesEnabled remain <strong>false</strong>. Do not close ticket01 as Done until the remaining test.md gates and inventory work are resolved. See <a href="./rollout.html">rollout.md</a> for activation and recovery.</p>',17)])])}const g=t(o,[["render",n]]);export{m as __pageData,g as default};
